// High-quality 3D icons (Icons8 3D Fluency, free with attribution).
// Inlined as data URIs because binary assets can't be pushed reliably.
// Attribution: 3D icons by Icons8 — see Settings > About.
var ICONS3D = {
  period: 'data:image/png;base64,',
  fertile: 'data:image/png;base64,',
  ovulation: 'data:image/png;base64,',
  calendar: 'data:image/png;base64,',
  log: 'data:image/png;base64,',
  advice: 'data:image/png;base64,',
  insights: 'data:image/png;base64,',
  history: 'data:image/png;base64,',
  settings: 'data:image/png;base64,',
  home: 'data:image/png;base64,',
  avatar: 'data:image/png;base64,',
  bell: 'data:image/png;base64,',
  moon: 'data:image/png;base64,',
  sun: 'data:image/png;base64,',
  plus: 'data:image/png;base64,',
  export: 'data:image/png;base64,',
  import: 'data:image/png;base64,',
  refresh: 'data:image/png;base64,',
  delete: 'data:image/png;base64,',
  save: 'data:image/png;base64,',
  chart: 'data:image/png;base64,',
  heart: 'data:image/png;base64,',
};

// <img> tag for a 3D icon. extra = additional CSS classes.
function icon3d(name, extra) {
  const src = ICONS3D[name] || '';
  return `<img src="${src}" class="ic3d${extra ? ' ' + extra : ''}" alt="" draggable="false">`;
}
// Hydrate static <span data-icon="name"></span> placeholders in one pass.
function hydrateIcons(root) {
  (root || document).querySelectorAll('span[data-icon]').forEach(s => {
    const src = ICONS3D[s.dataset.icon];
    if (!src) return;
    const img = document.createElement('img');
    img.src = src; img.alt = ''; img.draggable = false;
    img.className = 'ic3d' + (s.dataset.cls ? ' ' + s.dataset.cls : '');
    s.replaceWith(img);
  });
}